int main() {
    const string DIRS = "NESW";
    const int DX[] = {0, 1, 0, -1}, DY[] = {1, 0, -1, 0};
    int maxX, maxY;
    cin >> maxX >> maxY;
    set<pair<int, int>> scent;
    int x, y;
    char facing;
    string commands;
    while (cin >> x >> y >> facing >> commands) {
        int d = DIRS.find(facing);
        bool lost = false;
        for (char c : commands) {
            if (c == 'L') d = (d + 3) % 4;
            else if (c == 'R') d = (d + 1) % 4;
            else if (c == 'F') {
                int nx = x + DX[d], ny = y + DY[d];
                if (nx >= 0 && nx <= maxX && ny >= 0 && ny <= maxY) {
                    x = nx;
                    y = ny;
                } else if (!scent.count({x, y})) {
                    scent.insert({x, y});
                    lost = true;
                    break;
                }
            }
        }
        cout << x << " " << y << " " << DIRS[d] << (lost ? " LOST" : "") << "\n";
    }
    return 0;
}

