#include <iostream>
#include <set>
#include <string>
#include <vector>
using namespace std;

typedef vector<string> Board;

Board rotate(const Board& b) {
    int n = b.size();
    Board r(n, string(n, '.'));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) r[j][n - 1 - i] = b[i][j];
    return r;
}

int main() {
    int n;
    while (cin >> n && n) {
        Board board(n, string(n, '.'));
        set<Board> seen;
        string result = "Draw";
        for (int move = 1; move <= 2 * n; move++) {
            int r, c;
            char sign;
            cin >> r >> c >> sign;
            if (result != "Draw") continue;
            board[r - 1][c - 1] = (sign == '+') ? '#' : '.';
            Board shape = board;
            bool repeated = false;
            for (int t = 0; t < 4; t++) {
                if (seen.count(shape)) repeated = true;
                shape = rotate(shape);
            }
            if (repeated) result = "Player " + to_string(move % 2 ? 2 : 1) + " wins on move " + to_string(move);
            else seen.insert(board);
        }
        cout << result << "\n";
    }
    return 0;
}

