import sys


def reaches(q, t, k):
    """Can a queen on q move to t, with the king on k blocking?"""
    if q == t:
        return False
    qr, qc, tr, tc = q // 8, q % 8, t // 8, t % 8
    if qr != tr and qc != tc:
        return False
    step = 1 if qr == tr else 8
    if t < q:
        step = -step
    s = q
    while s != t:
        s += step
        if s == k:
            return False
    return True


def neighbours(s):
    r, c = s // 8, s % 8
    result = []
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        if 0 <= r + dr < 8 and 0 <= c + dc < 8:
            result.append((r + dr) * 8 + c + dc)
    return result


data = list(map(int, sys.stdin.read().split()))
out = []
for i in range(0, len(data) - 2, 3):
    king, queen, target = data[i], data[i + 1], data[i + 2]
    if king == queen:
        out.append("Illegal state")
    elif not reaches(queen, target, king):
        out.append("Illegal move")
    elif target in neighbours(king):
        out.append("Move not allowed")
    elif all(reaches(target, s, king) for s in neighbours(king)):
        out.append("Stop")
    else:
        out.append("Continue")
print("\n".join(out))

