#include <cstdio>
#include <vector>
using namespace std;

bool reaches(int q, int t, int k) {
    if (q == t) return false;
    if (q / 8 != t / 8 && q % 8 != t % 8) return false;
    int step = (q / 8 == t / 8) ? 1 : 8;
    if (t < q) step = -step;
    for (int s = q; s != t;) {
        s += step;
        if (s == k) return false;
    }
    return true;
}

vector<int> neighbours(int s) {
    int r = s / 8, c = s % 8;
    vector<int> result;
    if (r > 0) result.push_back(s - 8);
    if (r < 7) result.push_back(s + 8);
    if (c > 0) result.push_back(s - 1);
    if (c < 7) result.push_back(s + 1);
    return result;
}

int main() {
    int king, queen, target;
    while (scanf("%d %d %d", &king, &queen, &target) == 3) {
        if (king == queen) { puts("Illegal state"); continue; }
        if (!reaches(queen, target, king)) { puts("Illegal move"); continue; }
        vector<int> around = neighbours(king);
        bool adjacent = false, canMove = false;
        for (int s : around) {
            if (s == target) adjacent = true;
            if (!reaches(target, s, king)) canMove = true;
        }
        if (adjacent) puts("Move not allowed");
        else puts(canMove ? "Continue" : "Stop");
    }
    return 0;
}

