#include <cstdio>
#include <vector>
using namespace std;

int main() {
    const int LIMIT = 31623;
    vector<bool> composite(LIMIT + 1, false);
    vector<long long> primes;
    for (int i = 2; i <= LIMIT; i++) {
        if (composite[i]) continue;
        primes.push_back(i);
        for (long long j = (long long) i * i; j <= LIMIT; j += i) composite[j] = true;
    }
    int cases;
    scanf("%d", &cases);
    while (cases--) {
        long long low, high;
        scanf("%lld %lld", &low, &high);
        int size = high - low + 1;
        vector<long long> rest(size);
        vector<int> count(size, 1);
        for (int i = 0; i < size; i++) rest[i] = low + i;
        for (long long p : primes) {
            if (p * p > high) break;
            for (long long n = (low + p - 1) / p * p; n <= high; n += p) {
                int i = n - low, e = 0;
                while (rest[i] % p == 0) { rest[i] /= p; e++; }
                count[i] *= e + 1;
            }
        }
        long long best = low;
        int bestCount = 0;
        for (int i = 0; i < size; i++) {
            int c = rest[i] > 1 ? count[i] * 2 : count[i];
            if (c > bestCount) { best = low + i; bestCount = c; }
        }
        printf("Between %lld and %lld, %lld has a maximum of %d divisors.\n", low, high, best, bestCount);
    }
    return 0;
}

