#include <cstdio>

int main() {
    const int LIMIT = 30000;
    int coins[] = {1, 5, 10, 25, 50};
    static long long ways[LIMIT + 1] = {1};
    for (int coin : coins)
        for (int amount = coin; amount <= LIMIT; amount++) ways[amount] += ways[amount - coin];
    int n;
    while (scanf("%d", &n) == 1) {
        if (ways[n] == 1) printf("There is only 1 way to produce %d cents change.\n", n);
        else printf("There are %lld ways to produce %d cents change.\n", ways[n], n);
    }
    return 0;
}

