        int n = s.size();
        bool palindrome = true, mirrored = true;
        for (int i = 0; i < n; i++) {
            char other = s[n - 1 - i];
            if (s[i] != other) palindrome = false;
            if (!mirror.count(s[i]) || mirror[s[i]] != other) mirrored = false;
        }
        const char* message = palindrome ? (mirrored ? "is a mirrored palindrome." : "is a regular palindrome.")
