#include <iostream>
#include <map>
#include <string>
using namespace std;

map<string, int> position;

void build(string word, char next, int length) {
    if ((int) word.size() == length) {
        int number = position.size() + 1;
        position[word] = number;
        return;
    }
    for (char c = next; c <= 'z'; c++) build(word + c, c + 1, length);
}

int main() {
    for (int length = 1; length <= 5; length++) build("", 'a', length);
    string word;
    while (cin >> word) {
        auto it = position.find(word);
        cout << (it == position.end() ? 0 : it->second) << "\n";
    }
    return 0;
}

