        istringstream orderIn(line);
        vector<int> order;
        int index;
        while (orderIn >> index) order.push_back(index);
        nextLine(line);
        istringstream valueIn(line);
        vector<string> result(order.size());
        for (size_t i = 0; i < order.size(); i++) valueIn >> result[order[i] - 1];
        if (c) cout << "\n";
