int main() {
    int a, b, caseNumber = 0;
    while (scanf("%d %d", &a, &b) == 2 && !(a < 0 && b < 0)) {
        set<int> nodes;
        map<int, int> indegree;
        map<int, vector<int>> children;
        while (!(a == 0 && b == 0)) {
            nodes.insert(a);
            nodes.insert(b);
            indegree[b]++;
            children[a].push_back(b);
            scanf("%d %d", &a, &b);
        }
        caseNumber++;
        vector<int> roots;
        bool tree = true;
        for (int x : nodes) {
            if (indegree[x] == 0) roots.push_back(x);
            if (indegree[x] > 1) tree = false;
        }
        if (roots.size() != 1) tree = false;
        if (tree) {
            set<int> seen = {roots[0]};
            vector<int> stack = {roots[0]};
            while (!stack.empty()) {
                int x = stack.back();
                stack.pop_back();
                for (int child : children[x])
                    if (seen.insert(child).second) stack.push_back(child);
            }
            tree = seen.size() == nodes.size();
        }
        if (tree) printf("Case %d is a tree. Root is %d.\n", caseNumber, roots[0]);
        else printf("Case %d is not a tree.\n", caseNumber);
    }
    return 0;
}

