            string row;
            for (size_t i = 0; i < number.size(); i++) {
                if (i) row += ' ';
                row += (lit(number[i], left) ? '|' : ' ') + string(s, ' ') + (lit(number[i], right) ? '|' : ' ');
            }
            for (int r = 0; r < s; r++) cout << row << "\n";
        };
        horizontal(0);
        vertical(1, 2);
        horizontal(3);
        vertical(4, 5);
        horizontal(6);
        cout << "\n";
