using namespace std;

string multiply(const string& a, const string& b) {
    vector<int> result(a.size() + b.size(), 0);
    for (int i = a.size() - 1; i >= 0; i--)
        for (int j = b.size() - 1; j >= 0; j--)
            result[(a.size() - 1 - i) + (b.size() - 1 - j)] += (a[i] - '0') * (b[j] - '0');
    for (size_t k = 0; k + 1 < result.size(); k++) {
        result[k + 1] += result[k] / 10;
        result[k] %= 10;
    }
    int top = result.size() - 1;
    while (top > 0 && result[top] == 0) top--;
    string digits;
    for (int k = top; k >= 0; k--) digits += char('0' + result[k]);
    return digits;
}

int main() {
    string a, b;
    while (cin >> a >> b) cout << multiply(a, b) << "\n";
    return 0;
}

