#include <algorithm>
#include <functional>
using namespace std;

int main() {
    int cases;
    scanf("%d", &cases);
    while (cases--) {
        vector<long long> costs;
        long long cost;
        while (scanf("%lld", &cost) == 1 && cost != 0) costs.push_back(cost);
        sort(costs.begin(), costs.end(), greater<long long>());
        const long long LIMIT = 5000000;
        long long total = 0;
        bool tooExpensive = false;
        for (size_t t = 0; t < costs.size() && !tooExpensive; t++) {
            long long power = 1;
            for (size_t k = 0; k <= t; k++) {
                power *= costs[t];
                if (power > LIMIT) { tooExpensive = true; break; }
            }
            total += 2 * power;
            if (total > LIMIT) tooExpensive = true;
        }
        if (tooExpensive) printf("Too expensive\n");
        else printf("%lld\n", total);
    }
}

